mapper.select:

SELECT b.NUM, 'R' AS SENSING, IFNULL(a.RAIN, -99999) AS RAIN 
	FROM ( SELECT RAIN, DATE_FORMAT(RAIN_DATE, #{format}) AS NUM
			FROM RAIN_HIST
			WHERE DATA_TYPE = #{type} AND AREA_CODE = #{area_code} 
			AND RAIN_DATE IN (${where_date}) ) AS a
	RIGHT JOIN ( SELECT NUM 
				FROM STATISTICS_TMP
				WHERE TYPE = #{type}

		 AND NUM <=  #{ecnt}

	) AS b ON a.NUM = b.NUM 
	ORDER BY b.NUM

select.if:
